-- Add supplied industry page images without resetting text or visibility.
begin;
do $$
declare s public.cms_sections%rowtype; entry jsonb; updated jsonb; target_path text[]; parent_path text[];
begin
 for s in select * from public.cms_sections where (page_id='industries' or page_id like 'industries--%') for update loop
  updated := s.data;
  for entry in select value from jsonb_array_elements('[{"page": "industries--automotive", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/industries/automotive/logo-1.png"}, {"page": "industries--automotive", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/industries/automotive/logo-2.png"}, {"page": "industries--automotive", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/industries/automotive/logo-3.png"}, {"page": "industries--automotive", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/industries/automotive/logo-4.png"}, {"page": "industries--automotive", "section": "sectionOne", "path": ["image"], "image": "/industries/automotive/section-1-main-image.png"}, {"page": "industries--automotive", "section": "sectionThree", "path": ["image"], "image": "/industries/automotive/section-2-main-image.png"}, {"page": "industries--automotive", "section": "sectionFour", "path": ["services", "0", "image"], "image": "/industries/automotive/section-4-image-1.png"}, {"page": "industries--automotive", "section": "sectionFour", "path": ["services", "1", "image"], "image": "/industries/automotive/section-4-image-2.png"}, {"page": "industries--automotive", "section": "sectionFour", "path": ["services", "2", "image"], "image": "/industries/automotive/section-4-image-3.png"}, {"page": "industries--automotive", "section": "sectionFour", "path": ["services", "3", "image"], "image": "/industries/automotive/section-4-image-4.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/industries/chemicals-and-petrochemicals/logo-1.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/industries/chemicals-and-petrochemicals/logo-2.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/industries/chemicals-and-petrochemicals/logo-3.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/industries/chemicals-and-petrochemicals/logo-4.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/industries/chemicals-and-petrochemicals/logo-5.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionOne", "path": ["image"], "image": "/industries/chemicals-and-petrochemicals/section-1-main-image.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFour", "path": ["services", "0", "image"], "image": "/industries/chemicals-and-petrochemicals/section-4-image-1.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFour", "path": ["services", "1", "image"], "image": "/industries/chemicals-and-petrochemicals/section-4-image-2.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFour", "path": ["services", "2", "image"], "image": "/industries/chemicals-and-petrochemicals/section-4-image-3.png"}, {"page": "industries--chemicals-petrochemicals", "section": "sectionFour", "path": ["services", "3", "image"], "image": "/industries/chemicals-and-petrochemicals/section-4-image-4.png"}, {"page": "industries--construction-engineering", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/industries/construction-and-engineering/logo-1.png"}, {"page": "industries--construction-engineering", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/industries/construction-and-engineering/logo-2.png"}, {"page": "industries--construction-engineering", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/industries/construction-and-engineering/logo-3.png"}, {"page": "industries--construction-engineering", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/industries/construction-and-engineering/logo-4.png"}, {"page": "industries--construction-engineering", "section": "sectionOne", "path": ["image"], "image": "/industries/construction-and-engineering/section-1-main-image.png"}, {"page": "industries--construction-engineering", "section": "sectionFour", "path": ["services", "0", "image"], "image": "/industries/construction-and-engineering/section-4-image-1.png"}, {"page": "industries--construction-engineering", "section": "sectionFour", "path": ["services", "1", "image"], "image": "/industries/construction-and-engineering/section-4-image-2.png"}, {"page": "industries--construction-engineering", "section": "sectionFour", "path": ["services", "2", "image"], "image": "/industries/construction-and-engineering/section-4-image-3.png"}, {"page": "industries--construction-engineering", "section": "sectionFour", "path": ["services", "3", "image"], "image": "/industries/construction-and-engineering/section-4-image-4.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/industries/manufacturing-and-industrial/logo-1.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/industries/manufacturing-and-industrial/logo-2.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/industries/manufacturing-and-industrial/logo-3.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/industries/manufacturing-and-industrial/logo-4.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/industries/manufacturing-and-industrial/logo-5.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFive", "path": ["clients", "5", "image"], "image": "/industries/manufacturing-and-industrial/logo-6.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionOne", "path": ["image"], "image": "/industries/manufacturing-and-industrial/section-1-main-image.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFour", "path": ["services", "0", "image"], "image": "/industries/manufacturing-and-industrial/section-4-image-1.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFour", "path": ["services", "1", "image"], "image": "/industries/manufacturing-and-industrial/section-4-image-2.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFour", "path": ["services", "2", "image"], "image": "/industries/manufacturing-and-industrial/section-4-image-3.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFour", "path": ["services", "3", "image"], "image": "/industries/manufacturing-and-industrial/section-4-image-4.png"}, {"page": "industries--manufacturing-industrial", "section": "sectionFour", "path": ["services", "4", "image"], "image": "/industries/manufacturing-and-industrial/section-4-image-5.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFive", "path": ["clients", "0", "image"], "image": "/industries/oil-gas-and-energy/logo-1.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFive", "path": ["clients", "1", "image"], "image": "/industries/oil-gas-and-energy/logo-2.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFive", "path": ["clients", "2", "image"], "image": "/industries/oil-gas-and-energy/logo-3.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFive", "path": ["clients", "3", "image"], "image": "/industries/oil-gas-and-energy/logo-4.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFive", "path": ["clients", "4", "image"], "image": "/industries/oil-gas-and-energy/logo-5.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFive", "path": ["clients", "5", "image"], "image": "/industries/oil-gas-and-energy/logo-6.png"}, {"page": "industries--oil-gas-energy", "section": "sectionOne", "path": ["image"], "image": "/industries/oil-gas-and-energy/section-1-main-image.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFour", "path": ["services", "0", "image"], "image": "/industries/oil-gas-and-energy/section-4-image-1.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFour", "path": ["services", "1", "image"], "image": "/industries/oil-gas-and-energy/section-4-image-2.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFour", "path": ["services", "2", "image"], "image": "/industries/oil-gas-and-energy/section-4-image-3.png"}, {"page": "industries--oil-gas-energy", "section": "sectionFour", "path": ["services", "3", "image"], "image": "/industries/oil-gas-and-energy/section-4-image-4.png"}, {"page": "industries", "section": "sectionOne", "path": ["image"], "image": "/industries/overview/section-1-main-image.png"}, {"page": "industries", "section": "sectionTwo", "path": ["industries", "0", "image"], "image": "/industries/overview/section-2-image-1.png"}, {"page": "industries", "section": "sectionTwo", "path": ["industries", "1", "image"], "image": "/industries/overview/section-2-image-2.png"}, {"page": "industries", "section": "sectionTwo", "path": ["industries", "2", "image"], "image": "/industries/overview/section-2-image-3.png"}, {"page": "industries", "section": "sectionTwo", "path": ["industries", "3", "image"], "image": "/industries/overview/section-2-image-4.png"}, {"page": "industries", "section": "sectionTwo", "path": ["industries", "4", "image"], "image": "/industries/overview/section-2-image-5.png"}]'::jsonb) loop
   if entry->>'page'=s.page_id and entry->>'section'=s.key then
    select array_agg(value order by ord) into target_path from jsonb_array_elements_text(entry->'path') with ordinality as a(value,ord);
    parent_path := target_path[1:cardinality(target_path)-1];
    if cardinality(target_path)=1 or (jsonb_typeof(updated#>parent_path)='object' and updated#>parent_path<>'{}'::jsonb) then
     updated := jsonb_set(updated,target_path,entry->'image');
    end if;
   end if;
  end loop;
  if updated is distinct from s.data then
   update public.cms_sections set data=updated,revision=revision+1,updated_at=now() where page_id=s.page_id and key=s.key;
   insert into public.cms_history(actor,actor_id,page_id,section,revision,changes)
   values('System: Industry page images added','00000000-0000-0000-0000-000000000000'::uuid,s.page_id,s.key,s.revision+1,public.cms_diff(s.data,updated));
  end if;
 end loop;
end $$;
commit;
